import{_ as a,o,c as e,ag as n}from"./chunks/framework.DGzMGr_a.js";const u=JSON.parse('{"title":"RO3「启燃测试」6月25日开跑！台服招募即日开放","description":"RO3 台港澳「启燃测试」正式宣布，6月25日至7月2日举行，即日起开放招募。本次测试将开放PC自定义界面、五人MVP副本、十人副本等核心内容。","frontmatter":{"title":"RO3「启燃测试」6月25日开跑！台服招募即日开放","date":"2026-06-05T00:00:00.000Z","description":"RO3 台港澳「启燃测试」正式宣布，6月25日至7月2日举行，即日起开放招募。本次测试将开放PC自定义界面、五人MVP副本、十人副本等核心内容。"},"headers":[],"relativePath":"news/ignition-test-announced.md","filePath":"news/ignition-test-announced.md","lastUpdated":1781699082000}'),r={name:"news/ignition-test-announced.md"};function i(s,t,l,p,d,c){return o(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="ro3「启燃测试」6月25日开跑-台服招募即日开放" tabindex="-1">RO3「启燃测试」6月25日开跑！台服招募即日开放 <a class="header-anchor" href="#ro3「启燃测试」6月25日开跑-台服招募即日开放" aria-label="Permalink to &quot;RO3「启燃测试」6月25日开跑！台服招募即日开放&quot;">​</a></h1><blockquote><p>2026-06-05</p></blockquote><p>今天巴哈姆特发布了RO3的重大消息：台港澳地区的「启燃测试」正式确定，6月25日到7月2日举行，今天就开始招募了。这个测试等了大半年，总算来了。</p><h2 id="测试基本信息" tabindex="-1">测试基本信息 <a class="header-anchor" href="#测试基本信息" aria-label="Permalink to &quot;测试基本信息&quot;">​</a></h2><ul><li><strong>测试名称</strong>：启燃测试（技术测试）</li><li><strong>招募时间</strong>：即日起 ~ 6月23日 18:00</li><li><strong>测试时间</strong>：6月25日 ~ 7月2日</li><li><strong>测试平台</strong>：PC + 手机（跨平台互通）</li><li><strong>测试性质</strong>：免费、删档测试</li><li><strong>报名方式</strong>：官网预约，审核制</li></ul><p>这次测试是删档的，主要是做技术验证，不是最终上线版本。官方也说了，测试期间会集中开放内容做压力测试，节奏不代表正式上线后的情况。</p><h2 id="这次测什么" tabindex="-1">这次测什么 <a class="header-anchor" href="#这次测什么" aria-label="Permalink to &quot;这次测什么&quot;">​</a></h2><p>从巴哈姆特的报道来看，这次测试有几个重点值得关注：</p><p><strong>PC界面大改</strong>。之前测试被吐槽最多的就是PC版UI太手游化，这次专门加了&quot;高自由度使用者介面&quot;，可以自己调整界面布局和操作方式。看得出来官方确实在按开发者日志说的那样重做PC体验。</p><p><strong>五人MVP副本</strong>。以前RO的MVP都是野外抢的，这次改成五人副本形式，每个MVP有专属机制和行动模式。这个改动其实挺大的，等于把MVP从&quot;抢怪&quot;变成了&quot;打本&quot;，对休闲玩家更友好。</p><p><strong>十人副本</strong>。分为普通和高难度，强调团队配合和职业分工。十人本在RO3里一直宣传得比较多，这次终于能实际体验了。</p><p><strong>核心养成系统</strong>。天赋、装备、卡片这些经典系统都会开放验证，可以搭配不同的流派玩法。还有动态天气系统也会实装。</p><h2 id="怎么看这次测试" tabindex="-1">怎么看这次测试 <a class="header-anchor" href="#怎么看这次测试" aria-label="Permalink to &quot;怎么看这次测试&quot;">​</a></h2><p>这次测试离上次先锋测试隔了大半年，官方说是用这段时间根据玩家反馈做了大量调整。从开放的内容来看，PC端的优化确实是重点，这可能直接决定RO3在端游玩家心里的第一印象。</p><p>对玩家来说，这次测试最大的意义是可以实际摸到游戏了，尤其是PC版的操作手感、副本设计质量这些，看视频和亲自玩是两回事。如果你对RO3有兴趣，建议先去官网预约，审核制的话早报总比晚报好。</p><h2 id="国服呢" tabindex="-1">国服呢 <a class="header-anchor" href="#国服呢" aria-label="Permalink to &quot;国服呢&quot;">​</a></h2><p>国服仍然要等到2027年第一季度，比台服晚不少。想提前体验的可能要考虑玩台服测试了。不过删档测试嘛，主要就是体验一下游戏本身，不用太在意进度。</p><p>有新的测试消息我会继续更新，官网预约链接在下面：</p><p>➡ <a href="https://ro3global.com/zh-TW" target="_blank" rel="noreferrer">RO3官网预约</a></p>',19)])])}const g=a(r,[["render",i]]);export{u as __pageData,g as default};
